t.script:

(function () {
    function initPaymentPage() {
        var page = document.querySelector(".ut-pay-page");
        var statusBar = document.querySelector("[data-payment-status-bar]");
        var statusTitle = document.querySelector("[data-payment-status-title]");
        var statusCopy = document.querySelector("[data-payment-status-copy]");
        var referenceLabel = document.querySelector("[data-payment-reference-label]");
        var referenceValue = document.querySelector("[data-payment-reference-value]");
        var copyButton = document.querySelector("[data-copy-button]");
        var qrBlock = document.querySelector("[data-payment-qr]");
        var qrImage = document.querySelector("[data-payment-qr-image]");
        var xenditNote = document.querySelector("[data-payment-xendit-note]");
        var xenditLink = document.querySelector("[data-payment-xendit-link]");
        var primaryAction = document.querySelector("[data-payment-primary]");
        var countdownTimer = null;
        var pollTimer = null;

        function fallbackCopy(value) {
            var textarea = document.createElement("textarea");
            textarea.value = value;
            textarea.setAttribute("readonly", "readonly");
            textarea.style.position = "fixed";
            textarea.style.left = "-9999px";
            document.body.appendChild(textarea);
            textarea.focus();
            textarea.select();
            try {
                document.execCommand("copy");
            } catch (err) {
                console.warn("[UniTrade] Fallback copy failed:", err);
            }
            document.body.removeChild(textarea);
            return Promise.resolve();
        }

        function writeClipboard(value) {
            if (!navigator.clipboard || !navigator.clipboard.writeText || !document.hasFocus()) {
                return fallbackCopy(value);
            }
            try {
                return Promise.resolve(navigator.clipboard.writeText(value)).catch(function () {
                    return fallbackCopy(value);
                });
            } catch (err) {
                return fallbackCopy(value);
            }
        }

        document.querySelectorAll("[data-copy-value]").forEach(function (button) {
            button.addEventListener("click", function () {
                var value = button.getAttribute("data-copy-value") || "";
                if (!value) {
                    return;
                }
                writeClipboard(value).then(function () {
                    var label = button.querySelector("span");
                    if (!label) {
                        return;
                    }
                    var original = label.textContent;
                    label.textContent = "Tersalin";
                    window.setTimeout(function () {
                        label.textContent = original;
                    }, 1400);
                }).catch(function (err) {
                    console.warn("[UniTrade] Copy action failed:", err);
                });
            });
        });

        document.querySelectorAll("[data-payment-accordion-button]").forEach(function (button) {
            button.addEventListener("click", function () {
                var item = button.closest(".ut-pay-accordion-item");
                if (item) {
                    item.classList.toggle("is-open");
                }
            });
        });

        function setTone(tone) {
            if (!statusBar) {
                return;
            }
            statusBar.classList.remove("is-pending", "is-success", "is-danger");
            statusBar.classList.add("is-" + (tone || "pending"));
        }

        function stopCountdown() {
            if (countdownTimer) {
                window.clearInterval(countdownTimer);
                countdownTimer = null;
            }
        }

        function startCountdown() {
            var countdown = document.querySelector("[data-payment-countdown]");
            if (!statusBar || !countdown || !statusBar.dataset.expiredAt) {
                return;
            }
            var initialSeconds = parseInt(statusBar.dataset.expiresInSeconds || "0", 10) || 0;
            var expiry = initialSeconds > 0
                ? Date.now() + (initialSeconds * 1000)
                : new Date(statusBar.dataset.expiredAt.replace(" ", "T") + "Z").getTime();
            if (!expiry || Number.isNaN(expiry)) {
                return;
            }
            function tick() {
                if (page && page.dataset.paymentStatus !== "pending") {
                    stopCountdown();
                    return;
                }
                var remaining = Math.max(0, expiry - Date.now());
                var totalSeconds = Math.floor(remaining / 1000);
                var hours = String(Math.floor(totalSeconds / 3600)).padStart(2, "0");
                var minutes = String(Math.floor((totalSeconds % 3600) / 60)).padStart(2, "0");
                var seconds = String(totalSeconds % 60).padStart(2, "0");
                countdown.textContent = "Selesaikan pembayaran sebelum " + hours + ":" + minutes + ":" + seconds + " untuk memproses pesanan Anda.";
            }
            tick();
            countdownTimer = window.setInterval(tick, 1000);
        }

        function applyStatus(data) {
            if (!data || !data.status) {
                return;
            }
            if (data.status === "paid" && data.success_url) {
                window.location.href = data.success_url;
                return;
            }
            if (page) {
                page.dataset.paymentStatus = data.status;
            }
            setTone(data.tone);
            if (statusTitle && data.title) {
                statusTitle.textContent = data.title;
            }
            if (statusCopy && data.status !== "pending") {
                stopCountdown();
                statusCopy.textContent = data.message || "";
            } else if (statusCopy && !countdownTimer && data.message) {
                statusCopy.textContent = data.message;
            }
            if (referenceLabel && data.reference_label) {
                referenceLabel.textContent = data.reference_label;
            }
            if (referenceValue && data.reference) {
                referenceValue.textContent = data.reference;
            }
            if (copyButton && data.reference_raw) {
                copyButton.setAttribute("data-copy-value", data.reference_raw);
            }
            if (qrBlock && qrImage) {
                if (data.qr_image_url) {
                    qrImage.src = data.qr_image_url;
                    qrBlock.hidden = false;
                } else {
                    qrBlock.hidden = true;
                }
            }
            if (xenditNote) {
                xenditNote.hidden = Boolean(data.has_direct_reference) || Boolean(data.qr_image_url) || data.status !== "pending" || !data.payment_url;
            }
            if (xenditLink && data.payment_url) {
                xenditLink.href = data.payment_url;
            }
            if (primaryAction) {
                if (data.status === "paid") {
                    primaryAction.textContent = data.primary_label || "Lihat Pesanan";
                    primaryAction.href = data.primary_url || data.order_url || "/my/orders";
                } else if (["expired", "failed", "cancelled"].indexOf(data.status) !== -1) {
                    primaryAction.textContent = data.primary_label || "Kembali ke Checkout";
                    primaryAction.href = data.primary_url || "/shop/checkout";
                }
            }
            if (["paid", "expired", "failed", "cancelled"].indexOf(data.status) !== -1 && pollTimer) {
                window.clearInterval(pollTimer);
                pollTimer = null;
            }
        }

        function pollStatus() {
            if (!page || !page.dataset.paymentStatusUrl) {
                return;
            }
            fetch(page.dataset.paymentStatusUrl, {
                method: "GET",
                credentials: "same-origin",
                headers: {"Accept": "application/json"},
            }).then(function (response) {
                if (!response.ok) {
                    throw new Error("Payment status request failed");
                }
                return response.json();
            }).then(applyStatus).catch(function () {});
        }

        if (page && page.dataset.paymentStatus === "pending") {
            startCountdown();
            if (page.dataset.paymentStatusUrl) {
                window.setTimeout(pollStatus, 1500);
                pollTimer = window.setInterval(pollStatus, 7000);
            }
        }
    }

    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", initPaymentPage);
    } else {
        initPaymentPage();
    }
}());
